    /// <summary>
    /// The sheet for basement <paramref name="depth"/> (1 = LEVEL B1, the run's floor 2; FrontRooms3DGame.FloorLabel), full
    /// or Phase 0. Depth 10 and deeper: B10+. Null for depth 0 (LEVEL 0 hangs its own sheets) or less.
    /// </summary>
    public static Sheet For(int depth, bool full)
    {
        if (depth < 1) return null;
        return (full ? Full : Phase0)[Mathf.Min(depth, Depths) - 1];
    }

    /// <summary>Every sheet, full ones first (tools and tests).</summary>
    public static Sheet[] All()
    {
        var all = new Sheet[Full.Length + Phase0.Length];
        Full.CopyTo(all, 0);
        Phase0.CopyTo(all, Full.Length);
        return all;
    }

    /// <summary>A sheet's regions as EXAMINE takes them (a new array each call).</summary>
    public static InspectDef.Region[] Regions(Sheet sheet)
    {
        var n = RegionIds.Length;
        var regions = new InspectDef.Region[n];
        for (var i = 0; i < n; i++)
        {
            var k = i * 5;
            regions[i] = new InspectDef.Region
            {
                id = RegionIds[i],
                rect = new[] { sheet.regions[k], sheet.regions[k + 1], sheet.regions[k + 2], sheet.regions[k + 3] },
                capMm = sheet.regions[k + 4],
            };
        }
        return regions;
    }
}
